49	// returns pa
50	ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
51	{
52	    int i;
53	    for(i = 0; i < USER_PAGE_NUM; i++){
54	        if(user_page[i].valid == 0){
55	            break;
56	        }
57	    }
58	
59	    ptr_t pa;
60	    if(i == USER_PAGE_NUM){
61	        /* physical memory is exhausted: swap somebody else out first */
62	        pa = selete_page();
63	        write_to_sd(pa);
64	        i = pa2num(pa);
65	    }
66	    else{
67	        pa = num2pa(i);
68	    }
69	
70	    user_page[i].valid = 1;
71	    user_page[i].pin = pin;
72	    user_page[i].pgtable = pgtable;
73	
74	    /* a fresh page must not leak the previous owner's data */
75	    memset((void*)pa2kva(pa), 0, PAGE_SIZE);
76	    return pa;
77	}
