335	uintptr_t shm_page_get(int key)
336	{
337	    shm_page_t *page = &shm_page[(uint32_t)key % SHM_PAGE_NUM];
338	
339	    if(page->count == 0){
340	        /* first user of this key: give the group a pinned frame, it must
341	         * never be swapped out behind the back of the other sharers */
342	        page->pa = alloc_user_page(1, NULL);
343	    }
344	
345	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
346	    for(uintptr_t va = SHM_VA_BEGIN; va < SHM_VA_END; va += PAGE_SIZE){
347	        PTE *pte = walk_pgdir(va, pgdir);
348	        if(get_attribute(*pte, _PAGE_PRESENT) || get_attribute(*pte, _PAGE_SOFT)){
349	            continue;
350	        }
351	        *pte = 0;
352	        set_pfn(pte, page->pa >> NORMAL_PAGE_SHIFT);
353	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
354	                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
355	        page->count++;
356	        flush_tlb_all();
357	        return va;
358	    }
359	
360	    /* the share window of this process is full */
361	    if(page->count == 0){
362	        free_user_page(page->pa);
363	        page->pa = 0;
364	    }
365	    return 0;
366	}
367	
368	void shm_page_dt(uintptr_t addr)
369	{
370	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
371	    PTE *pte = find_pte(ROUNDDOWN(addr, PAGE_SIZE), pgdir);
372	
373	    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
374	        return;
375	    }
376	
377	    /* only a page that really belongs to a share group may be detached,
378	     * otherwise a bogus address would silently unmap private memory */
379	    uintptr_t pa = get_pa(*pte);
380	    for(int i = 0; i < SHM_PAGE_NUM; i++){
381	        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
382	            *pte = 0;
383	            flush_tlb_all();
384	
385	            shm_page[i].count--;
386	            if(shm_page[i].count == 0){
387	                free_user_page(pa);
388	                shm_page[i].pa = 0;
389	            }
390	            return;
391	        }
392	    }
393	}
394	
395	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
396	{
397	    /* Anything outside the user half of the Sv39 address space is a genuine
398	     * kernel bug; let the generic handler dump the context. */
399	    if(stval >= (1lu << (VPN2_SHIFT + PPN_BITS - 1))){
400	        handle_other(regs, stval, cause);
401	        return;
402	    }
403	
404	    /* demand paging: give the faulting address a frame (or fetch it back
405	     * from the swap area) and let the instruction run again */
406	    alloc_page_helper(stval, (uintptr_t)current_running[cpu_id]->pgdir);
407	}
