8	/*
9	 * Flush entire local TLB.  'sfence.vma' implicitly fences with the instruction
10	 * cache as well, so a 'fence.i' is not necessary.
11	 */
12	static inline void local_flush_tlb_all(void)
13	{
14	    __asm__ __volatile__ ("sfence.vma" : : : "memory");
15	}
16	
17	/* Flush one page from local TLB */
18	static inline void local_flush_tlb_page(unsigned long addr)
19	{
20	    __asm__ __volatile__ ("sfence.vma %0" : : "r" (addr) : "memory");
21	}
22	
23	static inline void local_flush_icache_all(void)
24	{
25	    asm volatile ("fence.i" ::: "memory");
26	}
27	
28	static inline void flush_tlb_all(void)
29	{
30	    local_flush_tlb_all();
31	    sbi_remote_sfence_vma(NULL, 0, -1);
32	}
33	
34	static inline void flush_tlb_page_all(unsigned long addr)
35	{
36	    local_flush_tlb_page(addr);
37	    sbi_remote_sfence_vma(NULL, 0, -1);
38	}
39	
40	static inline void flush_icache_all(void)
41	{
42	    local_flush_icache_all();
43	    sbi_remote_fence_i(NULL);
44	}
