179	/*
180	 * Load the ELF image called `file_name` into a brand new address space and
181	 * make it a runnable process.  The return value is the one the shell expects:
182	 * -1 when there is no such program, 0 when the process table is full, -2 when
183	 * memory ran out and the new pid on success.
184	 */
185	pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
186	{
187	    disable_preempt();
188	    /* file_name and argv live in the caller's user space */
189	    enable_sum();
190	
191	    unsigned char *binary = NULL;
192	    int length = 0;
193	    if (file_name == NULL || !get_elf_file(file_name, &binary, &length)) {
194	        disable_sum();
195	        enable_preempt();
196	        return -1;
197	    }
198	
199	    /* look for a free pcb: `pid == -1` marks an unused slot */
200	    int i;
201	    for (i = 0; i < NUM_MAX_TASK; i++) {
202	        if (pcb[i].pid == -1) {
203	            break;
204	        }
205	    }
206	    if (i == NUM_MAX_TASK) {
207	        disable_sum();
208	        enable_preempt();
209	        return 0;
210	    }
211	
212	    if (free_page_num() < EXEC_MIN_FREE_PAGES) {
213	        disable_sum();
214	        enable_preempt();
215	        return -2;
216	    }
217	
218	    pcb_t *new_pcb = &pcb[i];
219	    new_pcb->pgdir = init_page_table();
220	    /* the kernel stack is a pinned physical page used through the direct map */
221	    new_pcb->kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
222	    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
223	    new_pcb->user_sp = USER_STACK_ADDR;
224	    new_pcb->user_stack_base = USER_STACK_ADDR;
225	    new_pcb->preempt_count = 0;
226	    init_list_head(&new_pcb->wait_list);
227	    init_list_head(&new_pcb->timer.list);
228	    new_pcb->binsem_num = 0;
229	    new_pcb->pid = process_id++;
230	    new_pcb->type = USER_PROCESS;
231	    new_pcb->status = TASK_READY;
232	    new_pcb->mode = mode;
233	    new_pcb->priority = 1;
234	    new_pcb->ready_tick = get_ticks();
235	    /* a child may run wherever its parent was allowed to run */
236	    new_pcb->mask = current_running[cpu_id]->mask;
237	    if (new_pcb->mask == 0) {
238	        new_pcb->mask = (1UL << NR_CPUS) - 1;
239	    }
240	    new_pcb->cpu_id = cpu_id;
241	    new_pcb->cursor_x = 1;
242	    new_pcb->cursor_y = 1;
243	
244	    uintptr_t entry = load_elf(binary, (unsigned)length,
245	                               (uintptr_t)new_pcb->pgdir, alloc_page_helper);
246	    uintptr_t argv_va = init_user_stack(new_pcb, argc, argv);
247	
248	    init_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp, entry,
249	                   new_pcb, argc, argv_va);
250	    list_add_tail(&new_pcb->list, &ready_queue);
251	
252	    pid_t new_pid = new_pcb->pid;
253	    disable_sum();
254	    enable_preempt();
255	    return new_pid;
256	}
