290	/*
291	 * Finish the teardown of a task whose address space is already gone.  The
292	 * kernel stack is still in use at this point, so it is released later: either
293	 * by the parent in do_waitpid() or by the idle task of core 0.
294	 */
295	static void reclaim_pcb(pcb_t *task)
296	{
297	    list_del(&task->list);
298	
299	    if (task->mode == ENTER_ZOMBIE_ON_EXIT) {
300	        /* the parent reaps us in do_waitpid() */
301	        task->status = TASK_ZOMBIE;
302	    } else {
303	        task->status = TASK_EXITED;
304	        list_add_tail(&task->list, &kernel_pcb[0].wait_list);
305	    }
306	}
307	
308	void do_exit()
309	{
310	    disable_preempt();
311	    pcb_t *cur = current_running[cpu_id];
312	
313	    /* take ourselves out of the ready queue first: the wakeups below may
314	     * reschedule, which must not put a dying task back */
315	    list_del(&cur->list);
316	    release_resources(cur);
317	
318	    /* We are still running on this address space, so scheduler() performs the
319	     * teardown for us right after it has installed the next one. */
320	    cur->status = TASK_KILLED;
321	    scheduler();
322	
323	    enable_preempt();
324	}
