49	static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point, pcb_t *pcb)
50	{
51	    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
52	    pcb->kernel_sp -= sizeof(regs_context_t);
53	
54	    /* initialization registers: ra, sp, gp, sepc, sstatus, sepc, sscratch */
55	    pt_regs->regs[1] = (reg_t)entry_point;      //ra
56	    pt_regs->regs[2] = (reg_t)user_stack;       //sp
57	    pt_regs->regs[3] = (reg_t)__global_pointer$;//gp
58	    pt_regs->sstatus = (reg_t)SR_SPIE;          //SPP = 0, SPIE = 1
59	    pt_regs->sepc = (reg_t)entry_point;         //sepc
60	    pt_regs->sscratch = (reg_t)pcb;             //sscratch = tp
61	}
